head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 dataType이 time인 그리드뷰의 name2항목과 name3항목의 sum결과를 확인한다.
    //After executing the sample file, check the result of sum of name2 item and name3 item of grid view whose dataType is time.
    //Verify 1. 정상적인 time의 sum으로 결과가 보여진다. (이전에는 number로 sum 결과값이 보여짐)
    //The result is shown as a sum of normal time. (Formerly number shows sum result)
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("assert", "document.querySelector('#column8 nobr').innerHTML == '00:30'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.querySelector('#column7 nobr').innerHTML == '12:30'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
